    // Commands
    cmd_0: "No-context chat, isolated reply",
    cmd_1: "Use only the previous message as context",
    cmd_analyze: "Analyze the attached image/video with the vision model · add a question after the command to focus the analysis · -f/--frames N sets the video frame budget (default 8; keyframes picked at scene changes, near-duplicates deduped) · default analyzes one image/frame per call then synthesizes; -a/--all sends everything in one multi-image request (needs a model that accepts multiple images)",
    cmd_clear: "Clear current chat",
    cmd_compact: "Compress context, keep summary",
    analyze_imageSystem: "You are a professional image analysis expert. Examine the provided image(s) carefully and objectively, and produce a detailed, well-structured analysis. Cover the main subjects, scene and setting, notable objects, any visible text (transcribe it), colors and lighting, composition and style, and the likely context or intent. Be precise and concrete; only state what is actually visible, and clearly mark anything uncertain as an inference. Answer in the same language as the user's request.",
    analyze_videoSystem: "You are a professional video analysis expert. To analyze a video you are given several still frames sampled from it and sent as separate images IN CHRONOLOGICAL ORDER (the first image is the earliest frame, the last is the latest); refer to them by their order as frame #1, frame #2, and so on. The frames are different moments of a moving video, not copies of one image — compare consecutive frames to perceive motion and change, and never conclude the clip is static just because some frames look similar. Produce a detailed, well-structured, chronological analysis covering the scene, the main subjects, the action and how it progresses, any visible text (transcribe it), and the likely context or intent. Be precise; only state what is actually visible, and clearly mark anything uncertain as an inference. Answer in the same language as the user's request.",
    analyze_mixedSystem: "You are a professional visual analysis expert. The input combines standalone uploaded image(s) AND several still frames from a video, sent as separate images IN CHRONOLOGICAL ORDER (refer to the video frames by their order as frame #1, #2, …). You will be told how many uploads and how many video frames there are, and the video frames come last. Analyze the uploads and the video together: examine each uploaded image on its own; for the video, compare consecutive frames to perceive motion (they are different moments of a moving clip, not copies — don't call it static just because some look similar) and describe the action in order by frame number; then point out any relationship between the images and the video. Cover subjects, scene, notable objects, visible text (transcribe it), colors, composition, and likely context. Be precise; only state what is visible, and mark anything uncertain as an inference. Answer in the same language as the user's request.",
    analyze_imagePrompt: "Analyze the image(s) below in detail: describe the content, key objects, any visible text, colors, and overall style. If there are multiple images, analyze each one in turn, then compare and relate them.",
    analyze_videoPrompt: "The following ${frames} images are still frames from one video, sent in chronological order — treat them as frame #1, #2, … through #${frames}. They are different moments of a MOVING video, not copies — compare consecutive frames to detect motion, and do not call the clip static just because some frames look similar. Walk through the video in order and describe what happens, referring to frames by their number (e.g. \"frames #1–#3: …\", \"by frame #5 …\"). Also note the overall scene and main subjects.",
    analyze_mixedPrompt: "The first ${images} image(s) below are standalone uploads. The remaining ${frames} images are still frames from one video, sent in chronological order — treat them as frame #1, #2, … through #${frames}. First analyze each uploaded image in detail. Then describe the video in order, referring to frames by their number (e.g. \"frames #1–#3: …\"); the frames are different moments of a moving clip, so compare consecutive frames to detect motion and don't call it static just because some look similar. Finally, point out any connection between the uploaded images and the video.",
    analyze_extracting: "Extracting video frames",
    analyze_debugFrames: "🖼 The ${frames} extracted frames, in order:",
    analyze_frameMap: "Frame → time map (the model describes by frame number; use this to convert to seconds):",
    analyze_frameRow: "#${n} ${t}s",
    analyze_frameCaption: "#${n} · ${t}s",
    analyze_workingImage: "Analyzing image",
    analyze_workingVideo: "Analyzing video (${frames} frames)",
    analyze_workingMixed: "Analyzing images and video (${images} img + ${frames} frames)",
    analyze_noMedia: "⚠️ No image or video to analyze. Attach one and send /analyze, or use /analyze right after a bubble that contains media.",
    analyze_frameSceneLegend: "(⚡ = picked at a scene change; unmarked = evenly-spaced fill)",
    analyze_dedupDropped: "Dedup: ${n} near-duplicate frame(s) dropped.",
