    comfy_i2v_cmpRows: "wan14b‖Wan 2.2 14B‖最快 · 4步‖无‖弱(cfg1)‖首尾2帧‖让静图动起来\nwan5b‖Wan ti2v 5B‖快 · ~2秒‖无‖中‖—‖快速试构图\nltx‖LTX / Sulphur‖30步‖✓生成‖有效(cfg3)‖任意关键帧(≤8)‖要声音/提示词控内容\nphantom‖Phantom‖慢 · 50步‖无‖有效‖多主体参考‖保持人物身份\nltxmsr‖LTX-2.3 MSR‖8步 · 蒸馏‖✓生成‖中‖2–5主体参考‖保身份+要声音\nbernini‖Bernini‖中 · 可turbo‖无(i2v)‖中‖参考视角‖i2v兼视频编辑\ninfinitetalk‖InfiniteTalk‖6步‖✓你的语音/TTS‖仅画面‖—‖照片朗读文字(对口型)",
    comfy_model_unverified: "⚠️ 未验证：该模型尚未完整接入 / 真机测试，可能生成失败。仍可尝试。",
    comfy_image_group: "文生图",
