    tip_danceQuality: "仅 Wan Dancer：关键帧规划（global）阶段以完整质量运行——25 步 / cfg 5、不挂蒸馏 LoRA——替代默认的 6 步 turbo。慢得多；逐段精修阶段始终使用蒸馏配方。",
