    label_scailSubject: "追踪目标（SCAIL-2）",
    tip_scailSubject: "仅 SCAIL-2：在【源视频】里用大白话指定要追踪什么（SAM3 是开放词表）。默认 human。想在人群里点名某一个，就写描述，例如 person in a red shirt。也接受非人类目标（dog），但模型是拿人训练的。",
    label_scailRefSubject: "参考图里的目标（SCAIL-2）",
    tip_scailRefSubject: "仅 SCAIL-2：在【参考图】里追踪什么。留空 = 与源视频的追踪目标相同。只有两者不一致时才需要填 —— 例如源视频点名 person in a red shirt，而参考图里只有你的角色（human）。⚠️ 两边匹配到的【人数必须相同】：身份是按顺序绑定的，而且每一边都各自从 0 开始编号，所以数量对不上不会报错 —— 它会静默地把人配错。",
    label_scailThreshold: "检测阈值（SCAIL-2）",
    tip_scailThreshold: "仅 SCAIL-2：SAM3 要多有把握才算匹配上。0.5 = 默认，参考图和源视频同时生效。主要用途是【调低】——目标压根找不到时；调高通常没用，因为 SAM3 对认得出的目标本来就很有把握。注意：调低会让低置信度的杂物也被检出，它们会占掉目标槽位并使目标重新编号，改完请重新核对目标顺序。",
    label_scailMaxObjects: "最多追踪几个（SCAIL-2）",
    tip_scailMaxObjects: "仅 SCAIL-2：最多追踪多少个目标。4 = 默认，超出的会被静默丢掉 —— 人多时请调高。0 = 用节点自己的上限 64。注意参考图和源视频最终匹配到的【人数仍必须相同】。",
    label_scailIndices: "选用哪几个目标（SCAIL-2）",
    tip_scailIndices: "仅 SCAIL-2：按序号指定选用哪几个被追踪的目标，例如 0,2。留空 = 全部。序号的排法由下面的「目标排序」决定。最多追踪 4 个 —— 参考图里放多个人就会一次性全部替换。",
    warn_scailWindowVram: "⚠️ 这张卡只有 ${gb} GB，大窗口可能中途因显存失败（实测 736×1280 下 2x 在 32 GB 上放不下）。建议先用一小段试跑。",
    label_scailWindow: "窗口大小（SCAIL-2）",
    tip_scailWindow: "\u4ec5 SCAIL-2\uff1a\u6bcf\u4e00\u8d9f\u751f\u6210\u591a\u5c11\u5e27\u30021x \u662f\u5b98\u65b9\u6a21\u677f\u7528\u7684 81 \u5e27\u7a97\u53e3\uff0c2x/3x/4x \u5206\u522b\u653e\u5bbd\u5230 161/241/321\u300281 \u5e76\u4e0d\u662f\u6a21\u578b\u4e0a\u9650\u2014\u2014\u8282\u70b9\u672c\u8eab\u5141\u8bb8\u5230 16384\uff0c\u53c2\u8003\u5b9e\u73b0\u4e5f\u5f00\u653e\u4e86\u540c\u6837\u7684\u53c2\u6570\u2014\u2014\u800c\u4e14\u5728 432\u00d7768 \u5b9e\u6d4b\u5230 6 \u500d\u7a97\u53e3\u90fd\u6ca1\u6709\u753b\u8d28\u9000\u5316\uff0c122GB \u673a\u5668\u4e0a\u5168\u7a0b\u4e0d OOM\u3002\u4f46\u7a97\u53e3\u8d8a\u5927\u8d8a\u6162\uff0c\u4e0d\u662f\u8d8a\u5feb\uff1a\u540c\u6837\u8f93\u51fa 241 \u5e27\uff0c\u4e00\u4e2a\u5927\u7a97\u53e3\u7528\u4e86 827s\uff0c\u5207\u6210\u4e09\u6bb5 81 \u5e27\u53ea\u8981 490s\uff08\u5feb 1.69 \u500d\uff09\uff0c\u56e0\u4e3a\u6bcf\u5e27\u6210\u672c\u662f\u8d85\u7ebf\u6027\u4e0a\u6da8\u7684\u3002\u6240\u4ee5\u8c03\u5927\u5b83\u662f\u4e3a\u4e86\u300c\u8fde\u8d2f\u300d\u800c\u4e0d\u662f\u901f\u5ea6\u2014\u2014\u5b83\u80fd\u6d88\u9664\u5207\u6bb5\u5728\u957f\u955c\u5934\u6162\u52a8\u4f5c\u3001\u955c\u5934\u7f13\u79fb\u3001\u6216\u8005\u4e00\u4e2a\u8de8\u6bb5\u52a8\u4f5c\u4e0a\u7559\u4e0b\u7684\u63a5\u7f1d\u3002\u4ee3\u4ef7\uff1a\u8017\u65f6\u548c\u663e\u5b58\u5cf0\u503c\u5927\u81f4\u6309\u300c\u50cf\u7d20 \u00d7 \u5e27\u6570^1.45\u300d\u589e\u957f\uff0c\u6240\u4ee5 720p/1080p \u4e0b\u5f00 3x\u20134x \u5f88\u53ef\u80fd\u7206\u663e\u5b58\uff0c\u800c 1x \u5b8c\u5168\u591f\u7528\u3002\u957f\u7247\u4e4b\u524d\u5148\u5728\u76ee\u6807\u5206\u8fa8\u7387\u4e0a\u8bd5\u8dd1\u4e00\u6bb5\u3002",
    comfy_scailWindow_1x: "1x \u00b7 81 帧（默认）",
    comfy_scailWindow_2x: "2x \u00b7 161 帧",
    comfy_scailWindow_3x: "3x \u00b7 241 帧",
    comfy_scailWindow_4x: "4x \u00b7 321 帧",
    label_scailMemory: "长片内存策略（SCAIL-2 / Wan Animate）",
    tip_scailMemory: "仅 SCAIL-2：长片的内存开销怎么处理。随片长增长的东西有两样，这里选修掉哪些。默认档（推荐）两样都修。每个窗口一渲染完就写到磁盘，于是「生成出来的帧」不再堆积——旧路径会把每个窗口解码出的帧一直留到最后，实测每窗净涨约 3.7 GB，一段 110 秒的源因此爬到约 103 GB，在 122 GB 的机器上被杀掉。同时源视频按窗口逐段读取，于是「源」不再被整条解码并常驻内存供各段切片——110 秒 720p 约 27 GB，卡住的正是「源时长」而不是输出时长。之后由本机把各段拼起来并铺上原始声轨，和单文件路径的效果完全一致。「只逐段存盘」只做前一半：源仍会被整条解码。适用于 ComfyUI 那台没装 VideoHelperSuite，或你需要驱动帧的解码结果与从前完全一致——两种读源方式的色彩转换略有差异（约 39 dB，肉眼基本看不出，而且驱动视频只用于主体追踪和姿态条件），所以同一个 seed 在这一档和默认档之间会出得略有不同。「关闭」是原来的路径：ComfyUI 把所有窗口留在内存里，一次性出一条带音轨的成片。这一档不需要本机装 ffmpeg，几个窗口的短片用它完全没问题，但长片会耗尽内存。三档下窗口之间的重叠与颜色匹配都和从前一样——已在真机验证逐段读源取到的是同一批帧，接缝握手丝毫未动。Wan Animate 共用这个开关，但它只有输出侧这一半可修——它的源无论如何都会被整条解码（四个常驻节点，Replace 是六个），因为每段的 seek 是上一段在运行时算出来的、不是能交给逐段读取器的常数；在它上面前两档效果相同。",
    comfy_scailMemory_both: "逐段读源 + 逐段存盘（默认）",
    comfy_scailMemory_incremental: "只逐段存盘 \u00b7 源仍整条解码",
    comfy_scailMemory_off: "关闭 \u00b7 由 ComfyUI 一次出片，不需 ffmpeg",
    label_scailRecipe: "采样配方（SCAIL-2）",
    tip_scailRecipe: "\u4ec5 SCAIL-2\uff1a\u91c7\u6837\u6b65\u6570\u4e0e\u84b8\u998f LoRA \u7684\u6302\u8f7d\u5f3a\u5ea6\u3002\u5747\u8861\uff086 \u6b65 / \u5f3a\u5ea6 0.8\uff09\u662f\u672c\u5e94\u7528\u4e00\u76f4\u4ee5\u6765\u7684\u914d\u7f6e\u3002\u6fc0\u8fdb\uff084 \u6b65 / \u5168\u5f3a\u5ea6\uff09\u662f lightx2v \u4e3a\u8fd9\u4e2a LoRA \u5b98\u65b9\u7ed9\u51fa\u7684\u914d\u65b9\uff1a\u5728 RTX 5090 \u4e0a 736\u00d71280 \u5b9e\u6d4b 114s\uff0c\u5bf9\u5747\u8861\u7684 164s \u5feb 1.44 \u500d\uff0c\u9510\u5ea6\u6307\u6807\u53cd\u800c\u7565\u9ad8\uff0c\u624b\u90e8\u7ec6\u8282 2 \u500d\u653e\u5927\u4e0b\u770b\u4e0d\u51fa\u5dee\u522b\u3002\u4e4b\u6240\u4ee5\u4e0d\u8bbe\u4e3a\u9ed8\u8ba4\uff0c\u53ea\u662f\u56e0\u4e3a\u90a3\u6b21\u53ea\u6d4b\u4e86\u5355\u4eba\u7eaf\u80cc\u666f\u7684\u4e00\u6bb5\u821e\u8e48\u3002\u5173\u95ed turbo \u4f1a\u6458\u6389\u84b8\u998f LoRA\uff0c\u6539\u8dd1 40 \u6b65 / CFG 5 \u2014\u2014 DiT \u524d\u5411\u6b21\u6570\u7ea6\u4e3a\u5747\u8861\u6863\u7684 13 \u500d\uff0c\u6bcf\u6bb5\u8981\u51e0\u5341\u5206\u949f\u3002",
    comfy_scailRecipe_balanced: "均衡 \u00b7 6 步（默认）",
    comfy_scailRecipe_fast: "激进 \u00b7 4 步 \u00b7 快 1.44 倍",
    comfy_scailRecipe_off: "关闭 turbo \u00b7 40 步 \u00b7 很慢",
    label_scailSortBy: "目标排序（SCAIL-2）",
    tip_scailSortBy: "仅 SCAIL-2：目标的编号顺序，同时也决定参考图里的哪个人对应视频里的哪个人。先出现的帧越早排得越前；本项决定同一帧内的排法。left_to_right = 按位置从左到右，area = 面积最大的排第一，none = 保持 SAM3 自己的顺序。",
