    comfy_scailRefSubject_auto: "同上",
    comfy_scailIndices_all: "全部",
    label_poseStrength: "姿态强度（SCAIL-2）",
    tip_poseStrength: "仅 SCAIL-2：源视频的动作对角色的驱动力度。1 = 默认。调低会放松动作（角色体型和视频里的人差很多时有用），调高则更严格地贴合。",
    label_poseStart: "姿态引导起点（SCAIL-2）",
    tip_poseStart: "仅 SCAIL-2：姿态引导覆盖去噪过程的哪一段（按比例）。起点 0 / 终点 1 = 全程引导（默认）。终点小于 1 会让模型在后段自由发挥 —— 动作更松弛自然，代价是准确度下降。",
    label_poseEnd: "姿态引导终点（SCAIL-2）",
    tip_poseEnd: "仅 SCAIL-2：姿态引导在去噪过程的哪个比例处停止。1 = 全程引导（默认）。想要更松弛自然的动作可试 0.7–0.9。填得比起点小会被抬到起点。",
