    cmd_analyze: "用视觉模型分析附带的图片/视频 · 命令后可加问题以聚焦分析 · -f/--frames N 设置视频抽帧上限（默认 8，按场景变化选帧并去除近重复帧）· 默认逐张/逐帧分析后汇总；-a/--all 把全部图片一次性发给模型（需模型支持多图）",
    cmd_clear: "清空当前对话",
    cmd_compact: "压缩上下文，保留摘要",
    analyze_imageSystem: "你是一位专业的图片分析专家。请客观、仔细地观察所提供的图片，给出详细且条理清晰的分析，涵盖：主要对象、场景与环境、值得注意的物体、画面中的文字（请转写出来）、配色与光线、构图与风格，以及可能的背景或意图。描述要精确具体，只陈述画面中确实可见的内容；凡是推测的部分都要明确标注为推断。请用与用户提问相同的语言作答。",
    analyze_videoSystem: "你是一位专业的视频分析专家。分析视频时，你会收到从视频中截取的若干静止帧，它们作为独立图片按时间顺序传入（第一张是最早的帧，最后一张是最晚的）；请按它们的顺序称为第 1 帧、第 2 帧……。这些帧是一段运动视频的不同时刻，而非同一张图的复制——请对比相邻帧来感知运动与变化，切勿因为某些帧看起来相似就判定视频是静止的。请按时间顺序给出详细、条理清晰的分析，涵盖场景、主要对象、动作及其推进、画面中的文字（请转写出来），以及可能的背景或意图。描述要精确，只陈述确实可见的内容，凡推测都要标注为推断。请用与用户提问相同的语言作答。",
    analyze_mixedSystem: "你是一位专业的视觉分析专家。本次输入同时包含独立上传的图片，以及从一段视频中截取、作为独立图片按时间顺序传入的若干静止帧（请按顺序称为第 1 帧、第 2 帧……，视频帧排在最后）。系统会告诉你上传图片有几张、视频帧有几张。请把两者结合起来分析：对每张上传图片单独审视；对视频，对比相邻帧来感知运动（它们是运动视频的不同时刻而非复制，切勿因某些相似就判为静止），并按帧号顺序描述动作；再指出图片与视频之间可能的关联。涵盖主要对象、场景、值得注意的物体、画面中的文字（请转写出来）、配色、构图及可能的背景。描述要精确，只陈述可见内容，推测要标注。请用与用户提问相同的语言作答。",
    analyze_imagePrompt: "请详细分析下面的图片：描述内容、主要对象、其中的文字、配色以及整体风格。若有多张，请先逐张分析，再做整体对比与关联。",
    analyze_videoPrompt: "下面这 ${frames} 张是从同一段视频中按时间顺序截取的帧，依次为第 1 帧、第 2 帧……第 ${frames} 帧。它们是一段运动视频的不同时刻，并非同一张图的复制——请对比相邻帧来判断运动，切勿因某些帧看起来相似就判定视频是静止的。请按顺序描述视频发生了什么，用帧号来指代（如「第 1–3 帧：……」「到第 5 帧时……」），并交代整体场景与主要对象。",
    analyze_mixedPrompt: "下面的前 ${images} 张是独立上传的图片；其余 ${frames} 张是从同一段视频中按时间顺序截取的帧，依次为第 1 帧、第 2 帧……第 ${frames} 帧。请先逐张详细分析上传的图片；再按顺序描述视频，用帧号来指代（如「第 1–3 帧：……」）；这些帧是运动视频的不同时刻，请对比相邻帧判断运动，切勿因某些帧相似就判为静止；最后指出图片与视频之间的关联。",
