    analyze_itemImage: "图片 ${n}",
    analyze_itemFrame: "第 ${n} 帧（${t}s）",
    analyze_mapImageSystem: "你是一位专业的图片分析专家。请精确、具体地描述所给的这一张图片：主要对象、场景与环境、值得注意的物体、画面中的文字（请转写出来）、配色与光线、构图。只陈述画面中确实可见的内容，推测的部分要标注为推断，不要超出画面进行臆测。请用与用户提问相同的语言作答。",
    analyze_mapFrameSystem: "你是一位专业的视频分析专家。你收到的是从一段视频中截取的一张静止帧。请精确、具体地描述这一帧：主要对象及其此刻的姿态/动作、场景、值得注意的物体、画面中的文字（请转写出来）、配色、构图。只陈述这一帧中确实可见的内容，推测要标注为推断。你的描述之后会与其他帧的描述合并用于还原整段视频，因此请写明有助于跨帧追踪对象的细节（衣着、在画面中的位置、运动方向）。请用与用户提问相同的语言作答。",
    analyze_mapPrompt: "请详细描述${label}。",
    analyze_mapFocus: "请特别留意与下面这个问题相关的细节——现在不用回答问题，只需确保相关细节都被记录下来：${q}",
    analyze_mapNotes: "逐项笔记（每张图片/每帧各一次视觉调用）：",
    analyze_reduceSystem: "你是一位专业的视觉分析专家。你将收到对若干图片和/或视频帧的文字描述（每张由一次独立的视觉调用生成）；视频帧按时间顺序标注了帧号和时间戳。这些笔记是你唯一的信息来源——你看不到图片本身。请基于笔记还原它们呈现的内容，对比相邻帧的描述来推断运动与变化，并完成用户的要求。指代视频帧时请用帧号（如「第 3 帧」）。若笔记中某处信息不足或含混，请明确说明，不要猜测。请用与用户提问相同的语言作答。",
    analyze_reduceImageIntro: "以下是 ${images} 张上传图片的逐张描述：",
