    label_h3Clip: "H3 文字編碼器",
    tip_h3Clip: "僅 MiniMax H3。用哪個 Qwen3-VL-32B 文字編碼器讀你的提示詞：15.7 GB（nvfp4_awq）、27.1 GB（int8_convrot）或 51.5 GB（bf16）。在這份預算要和 21–40 GB 的擴散模型分帳的機器上，這是個真實取捨；它與上面的「模型精度」相互獨立——bf16 模型配 nvfp4 編碼器是合理組合。自動 = 優先量化版。",
