    tip_danceStyle: "僅 Wan Dancer：五種訓練過的舞種選其一。自動 = 從提示詞推斷（如寫「街舞」/「street dance」），推斷不出時預設拉丁舞。",
    tip_danceAmplitude: "僅 Wan Dancer：舞蹈動作的幅度大小。",
    tip_danceDuration: "僅 Wan Dancer：輸出時長（秒），每 5 秒為一個精修段。自動 = 跟隨所附音樂的長度，上限為模型的 30 秒天花板。時長越長，渲染時間成比例增加。",
    tip_danceQuality: "僅 Wan Dancer：關鍵幀規劃（global）階段以完整品質運行——25 步 / cfg 5、不掛蒸餾 LoRA——替代預設的 6 步 turbo。慢得多；逐段精修階段始終使用蒸餾配方。",
