    cmd_analyze: "用視覺模型分析附帶的圖片/視頻 · 命令後可加問題以聚焦分析 · -f/--frames N 設定視頻抽幀上限（預設 8，按場景變化選幀並去除近重複幀）· 預設逐張/逐幀分析後彙總；-a/--all 把全部圖片一次性發給模型（需模型支援多圖）",
    cmd_clear: "清空目前對話",
    cmd_compact: "壓縮上下文，保留摘要",
    analyze_imageSystem: "你是一位專業的圖片分析專家。請客觀、仔細地觀察所提供的圖片，給出詳細且條理清晰的分析，涵蓋：主要對象、場景與環境、值得注意的物體、畫面中的文字（請轉寫出來）、配色與光線、構圖與風格，以及可能的背景或意圖。描述要精確具體，只陳述畫面中確實可見的內容；凡是推測的部分都要明確標註為推斷。請用與使用者提問相同的語言作答。",
    analyze_videoSystem: "你是一位專業的視頻分析專家。分析視頻時，你會收到從視頻中截取的若干靜止幀，它們作為獨立圖片按時間順序傳入（第一張是最早的幀，最後一張是最晚的）；請按它們的順序稱為第 1 幀、第 2 幀……。這些幀是一段運動視頻的不同時刻，而非同一張圖的複製——請對比相鄰幀來感知運動與變化，切勿因為某些幀看起來相似就判定視頻是靜止的。請按時間順序給出詳細、條理清晰的分析，涵蓋場景、主要對象、動作及其推進、畫面中的文字（請轉寫出來），以及可能的背景或意圖。描述要精確，只陳述確實可見的內容，凡推測都要標註為推斷。請用與使用者提問相同的語言作答。",
    analyze_mixedSystem: "你是一位專業的視覺分析專家。本次輸入同時包含獨立上傳的圖片，以及從一段視頻中截取、作為獨立圖片按時間順序傳入的若干靜止幀（請按順序稱為第 1 幀、第 2 幀……，視頻幀排在最後）。系統會告訴你上傳圖片有幾張、視頻幀有幾張。請把兩者結合起來分析：對每張上傳圖片單獨審視；對視頻，對比相鄰幀來感知運動（它們是運動視頻的不同時刻而非複製，切勿因某些相似就判為靜止），並按幀號順序描述動作；再指出圖片與視頻之間可能的關聯。涵蓋主要對象、場景、值得注意的物體、畫面中的文字（請轉寫出來）、配色、構圖及可能的背景。描述要精確，只陳述可見內容，推測要標註。請用與使用者提問相同的語言作答。",
    analyze_imagePrompt: "請詳細分析下面的圖片：描述內容、主要對象、其中的文字、配色以及整體風格。若有多張，請先逐張分析，再做整體對比與關聯。",
    analyze_videoPrompt: "下面這 ${frames} 張是從同一段視頻中按時間順序截取的幀，依次為第 1 幀、第 2 幀……第 ${frames} 幀。它們是一段運動視頻的不同時刻，並非同一張圖的複製——請對比相鄰幀來判斷運動，切勿因某些幀看起來相似就判定視頻是靜止的。請按順序描述視頻發生了什麼，用幀號來指代（如「第 1–3 幀：……」「到第 5 幀時……」），並交代整體場景與主要對象。",
    analyze_mixedPrompt: "下面的前 ${images} 張是獨立上傳的圖片；其餘 ${frames} 張是從同一段視頻中按時間順序截取的幀，依次為第 1 幀、第 2 幀……第 ${frames} 幀。請先逐張詳細分析上傳的圖片；再按順序描述視頻，用幀號來指代（如「第 1–3 幀：……」）；這些幀是運動視頻的不同時刻，請對比相鄰幀判斷運動，切勿因某些幀相似就判為靜止；最後指出圖片與視頻之間的關聯。",
