    analyze_mapImageSystem: "你是一位專業的圖片分析專家。請精確、具體地描述所給的這一張圖片：主要對象、場景與環境、值得注意的物體、畫面中的文字（請轉寫出來）、配色與光線、構圖。只陳述畫面中確實可見的內容，推測的部分要標註為推斷，不要超出畫面進行臆測。請用與使用者提問相同的語言作答。",
    analyze_mapFrameSystem: "你是一位專業的視頻分析專家。你收到的是從一段視頻中截取的一張靜止幀。請精確、具體地描述這一幀：主要對象及其此刻的姿態/動作、場景、值得注意的物體、畫面中的文字（請轉寫出來）、配色、構圖。只陳述這一幀中確實可見的內容，推測要標註為推斷。你的描述之後會與其他幀的描述合併用於還原整段視頻，因此請寫明有助於跨幀追蹤對象的細節（衣著、在畫面中的位置、運動方向）。請用與使用者提問相同的語言作答。",
    analyze_mapPrompt: "請詳細描述${label}。",
