/** Apply current UI language to all static DOM text nodes */
export function applyUILanguage() {
  for (const { sel, key, attr } of BINDINGS) {
    const el = document.querySelector(sel);
    if (!el) continue;
    const text = t(key);
    if (attr === "placeholder") {
      el.placeholder = text;
    } else if (attr === "title") {
      el.title = text;
    } else if (attr === "firstText") {
      // Replace first text node only
      const textNode = Array.from(el.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
      if (textNode) textNode.textContent = text;
    } else if (attr === "lastText") {
      // Replace last text node (e.g. import button label after <input>)
      const nodes = Array.from(el.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
      if (nodes.length) nodes[nodes.length - 1].textContent = "\n              " + text + "\n            ";
    } else if (attr) {
      // Any other attribute name is set verbatim (e.g. data-* consumed by CSS attr()).
      el.setAttribute(attr, text);
    } else {
      el.textContent = text;
    }
  }
  // Update send button based on current state
  if (!dom.sendButton.classList.contains("isStop")) {
    dom.sendButton.textContent = t("btn_send");
  } else {
    dom.sendButton.textContent = t("btn_stop");
  }
  // File button
  const fileLabel = document.querySelector(".uploadButton");
  if (fileLabel) {
    const textNodes = Array.from(fileLabel.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
    if (textNodes.length) textNodes[textNodes.length - 1].textContent = "\n            " + t("btn_file") + "\n          ";
  }
  // Quick prompts
  // Quick prompt hint
  const qpHint = document.querySelector(".quickPromptHint");
  if (qpHint) qpHint.innerHTML = t("qp_hint").replace(/(\/\w+)/g, '<kbd>$1</kbd>');
  const qpItems = document.querySelectorAll(".quickPromptItem");
  const qpKeys = ["qp_understand", "qp_understandTable", "qp_understandTableSimple", "qp_table", "qp_simple", "qp_summarize", "qp_summarizeSimple"];
  qpItems.forEach((item, i) => {
    if (qpKeys[i]) {
      const text = t(qpKeys[i]);
      item.textContent = text;
      item.dataset.prompt = text;
    }
  });
  // Archive sort button (dynamic)
  const sortBtn = document.querySelector("#archiveSortBtn");
  if (sortBtn) {
    sortBtn.textContent = sortBtn.textContent.includes("→") ?
      (sortBtn.textContent.includes("New") || sortBtn.textContent.includes("新") ? t("archive_sortNewOld") : t("archive_sortOldNew")) :
      t("archive_sortNewOld");
  }
  // Library sort button (dynamic — current mode lives in dataset.mode)
  const libSortBtn = document.querySelector("#librarySortBtn");
  if (libSortBtn) {
    const m = libSortBtn.dataset.mode;
    libSortBtn.textContent = t(m === "importRev" ? "lib_sortImportRev" : m === "new" ? "lib_sortNewOld" : m === "old" ? "lib_sortOldNew" : m === "rate" ? "lib_sortRate" : "lib_sortDefault");
    libSortBtn.title = t("lib_sortHint");
  }
  const libRateFilter = document.querySelector("#libraryRatingFilter");
  if (libRateFilter) {
    for (const opt of libRateFilter.options) {
      if (opt.value === "") opt.textContent = t("lib_rateFilterAll");
      else if (opt.value === "unrated") opt.textContent = t("lib_rateFilterUnrated");
      else if (opt.value === "rated") opt.textContent = t("gal_rateFilterRated");
      else if (opt.value === "zero") opt.textContent = t("gal_rateFilterZero");
    }
  }
  // Gallery filter dropdowns (their options are static markup, unlike the model
  // list, which is built from whatever the gallery actually holds).
  const galType = document.querySelector("#galleryTypeFilter");
  if (galType) {
    for (const opt of galType.options) {
      const key = opt.value === "" ? "gal_allMedia" : opt.value === "image" ? "gal_typeImage"
        : opt.value === "video" ? "gal_typeVideo" : opt.value === "audio" ? "gal_typeAudio"
        : opt.value === "mesh" ? "gal_typeMesh" : null;
      if (key) opt.textContent = t(key);
    }
  }
  const galView = document.querySelector("#galleryViewFilter");
  if (galView) {
    for (const opt of galView.options) {
      const key = opt.value === "md" ? "gal_viewMedium" : opt.value === "sm" ? "gal_viewSmall"
        : "gal_viewList";
      opt.textContent = t(key);
    }
  }
  // The numeric rows (★5 / ★4+ / ★3+ / ★0) are the same glyphs in every language, so
  // only the three worded rows need translating.
  const galRating = document.querySelector("#galleryRatingFilter");
  if (galRating) {
    galRating.title = t("gal_ratingFilterTitle");
    for (const opt of galRating.options) {
      const key = opt.value === "" ? "gal_allRatings" : opt.value === "rated" ? "gal_rateFilterRated"
        : opt.value === "unrated" ? "gal_rateFilterUnrated" : opt.value === "zero" ? "gal_rateFilterZero" : null;
      if (key) opt.textContent = t(key);
    }
  }
  const galSource = document.querySelector("#gallerySourceFilter");
  if (galSource) {
    for (const opt of galSource.options) {
      const key = opt.value === "" ? "gal_srcAny" : opt.value === "tabs" ? "gal_srcTabs" : "gal_srcArchives";
      opt.textContent = t(key);
    }
  }
  // The model filter's options ARE built from the ledger, so only its "any" row is
  // translatable — and it needs doing here because the builder skips a rebuild when the
  // model set is unchanged, which is exactly the case on a bare language switch.
  const galModel = document.querySelector("#galleryModelFilter");
  const galModelAny = galModel && [...galModel.options].find((o) => o.value === "");
  if (galModelAny) galModelAny.textContent = t("gal_allModels");

  // Archive expand button
  const expandBtn = document.querySelector("#archiveExpandAllBtn");
  if (expandBtn) {
    expandBtn.textContent = t("archive_expand");
  }
  // Archive select all label
  const selectAllLabel = document.querySelector(".archiveSelectAll");
  if (selectAllLabel) {
    const textNode = Array.from(selectAllLabel.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
    if (textNode.length) textNode[textNode.length - 1].textContent = "\n              " + t("archive_selectAll") + "\n            ";
  }
  // AI name title
  if (dom.aiName) dom.aiName.title = t("msg_aiNameTitle");
  // Image-model dropdown: the always-present empty option is built by ollama.js
  // (loadImageModels) and not otherwise re-labeled on a language switch.
  if (dom.imageModelSelect) {
    const empty = dom.imageModelSelect.querySelector('option[value=""]');
    if (empty) empty.textContent = dom.imageModelSelect.options.length > 1 ? t("image_model_empty") : t("image_model_none");
  }
  // ComfyUI model dropdown is re-localized separately (relocalizeComfyModels in
  // the language-change handler) — it rebuilds optgroups, the i18n image-upscale
  // label, and capability dots from the cached dataset, which a per-node relabel
  // here couldn't reconstruct.
}

/** Get command list with localized descriptions */
export function getLocalizedCommands() {
  return [
    { name: "/0", desc: t("cmd_0") },
    { name: "/1", desc: t("cmd_1") },
    { name: "/analyze", desc: t("cmd_analyze") },
    { name: "/ask", desc: t("cmd_ask") },
    { name: "/clear", desc: t("cmd_clear") },
    { name: "/compact", desc: t("cmd_compact") },
    { name: "/imagine", desc: t("cmd_imagine") },
    { name: "/memory", desc: t("cmd_remember") },
    { name: "/note", desc: t("cmd_note") },
    { name: "/remind", desc: t("cmd_remind") },
    { name: "/search", desc: t("cmd_search") },
    { name: "/skill", desc: t("cmd_skill") },
    { name: "/tool", desc: t("cmd_tool") },
    { name: "/url", desc: t("cmd_url") },
    { name: "/voice", desc: t("cmd_voice") },
  ].sort((a, b) => a.name.localeCompare(b.name));
}